import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"更新日志 · XiHan Framework","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1793828433000}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="更新日志-·-xihan-framework" tabindex="-1">更新日志 · XiHan Framework <a class="header-anchor" href="#更新日志-·-xihan-framework" aria-label="Permalink to “更新日志 · XiHan Framework”">​</a></h1><p>本页记录 XiHan Framework 各版本中使用者可感知的变更，每条标注 <strong>新增 / 修复 / 优化 / 调整 / 移除</strong> 类别；仓库自身的 CI、测试工程与构建脚本不列入。</p><h2 id="v5-0-0-preview-1-2026-11-05" tabindex="-1">v5.0.0-preview.1（2026-11-05） <a class="header-anchor" href="#v5-0-0-preview-1-2026-11-05" aria-label="Permalink to “v5.0.0-preview.1（2026-11-05）”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">预览须知</p><ul><li>这是预览版，安装要带 <code>--prerelease</code>；公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整</li></ul></div><h3 id="原语与内核" tabindex="-1">原语与内核 <a class="header-anchor" href="#原语与内核" aria-label="Permalink to “原语与内核”">​</a></h3><ul><li><strong>新增</strong> 原语层 <code>Primitives</code>：<code>Result</code> / <code>Result&lt;T&gt;</code>、<code>Error</code> 与错误码文法、<code>Maybe&lt;T&gt;</code>、<code>TypedId</code>、<code>InvocationContext</code>、清单模型、<code>PipelineStage</code>、<code>LifecycleState</code>、<code>Stability</code> 与 <code>[ApiLevel]</code>，只增不改</li><li><strong>新增</strong> 内核 <code>Kernel</code>：<code>AddXiHan</code> + <code>UseFeature&lt;T&gt;()</code> 装配特性，按能力 ID 求解能力图谱，<code>XiHan:Providers:&lt;能力 ID&gt;</code> 或 <code>UseProvider</code> 选择 Provider，启动日志打印图谱与管道</li><li><strong>新增</strong> 十一个阶段的执行管道与内置中间件：截止时间、按操作 ID 的熔断 / 限流 / 并发上限（<code>XiHan:Kernel:Resilience</code>）、按 JSON Schema 与 <code>IValidatableObject</code> 的契约校验</li><li><strong>新增</strong> 操作契约与调用器：<code>[Operation]</code>、<code>IOperation&lt;TRequest, TResponse&gt;</code>、<code>OperationRegistry</code>、<code>IOperationInvoker</code>；<code>Kernel.Generators</code> 生成登记代码与请求 / 响应 JSON Schema（<code>XHG001</code>–<code>XHG006</code>），程序集级 <code>OperationDefaults</code> 与只读声明</li><li><strong>新增</strong> 九态生命周期、<code>/health/startup|ready|live</code> 探针、<code>IHealthContributor</code> 与周期探测的 <code>PeriodicHealthContributor</code>，健康条目带说明、检查时刻、耗时与标量数据</li><li><strong>新增</strong> 资源绑定（<code>XiHan:Bindings</code>、<code>SERVICE_BINDING_ROOT</code>）与配置目录 <code>XIHAN_CONFIG_PATH</code> 热更新</li><li><strong>新增</strong> <code>IInvocationAccessor</code> 与调用来源 <code>InvocationOrigin</code>（协议、请求目标、远端地址、User-Agent、端点路由与名字）</li><li><strong>新增</strong> 分析器 <code>Kernel.Analyzers</code>（XH0001–XH0005）与测试基座 <code>Testing</code></li><li><strong>新增</strong> <code>OutboundAddressPolicy.ConnectAsync(host, port, ct)</code>：不是 HTTP 但地址来自用户的连接（SMTP）用同样的规则，返回连好的 <code>Socket</code></li><li><strong>修复</strong> <code>MapXiHanBlobs</code> 的响应带 <code>X-Content-Type-Options: nosniff</code>，写出内容时除 PDF 外带沙箱的 <code>Content-Security-Policy</code>，用户上传的 HTML、SVG 不能在应用的源上运行脚本</li><li><strong>修复</strong> 载荷解码错误的 <code>reason</code> 只写 JSON 路径，不再把请求类型的全名回给调用方</li><li><strong>修复</strong> SqlSugar 的数据库健康项与运行时数据源探测走一次数据库往返并按配置超时：连接池里有空闲连接时不再在库宕了之后报健康，服务器不回话时不再卡住启动；<code>persistence.sqlsugar.database</code> 的错误码由 <code>PERSISTENCE_UNAVAILABLE_003</code> 变成 <code>KERNEL_UNAVAILABLE_005</code>；<code>TestAsync</code> 单次上限是运行时数据源的 <code>HealthProbeIntervalSeconds</code></li><li><strong>修复</strong> 配了从库时授予与租户目录读主库，撤销授予、停用租户的生效时间不再多出复制延迟；新增 <code>UnitOfWorkOptions.ReadsPrimary</code></li><li><strong>调整</strong> HTTP、gRPC、MCP 入站丢弃 Baggage 里的 <code>xihan.tenant</code> 与 <code>xihan.principal</code>，这些调用方的租户只来自认证（CloudEvents 入站不变，端点权限由宿主自己加）；要按主机名或请求头选租户时登记自己的 <code>ITenantResolver</code></li><li><strong>新增</strong> 出站地址策略 <code>OutboundAddressPolicy</code>：工作流 <code>Http</code> 活动、CloudEvents Webhook 与 S3 命名实例缺省只能连公网地址，连接时按实际 IP 判定；连本机或内网要在 <code>XiHan:Security:Outbound</code> 放行，本地开发写 <code>AllowLoopback: true</code>（见<a href="./guide/outbound">出站地址策略</a>）</li></ul><h3 id="子系统" tabindex="-1">子系统 <a class="header-anchor" href="#子系统" aria-label="Permalink to “子系统”">​</a></h3><ul><li><strong>新增</strong> 本地化：消息键与 <code>key.L()</code>、每种语言一个 <code>Localization/&lt;区域&gt;.json</code>、内置 10 种区域（默认 <code>en-US</code>）、宿主按 <code>Accept-Language</code> 翻译 Problem Details；<code>Localization.InMemory</code> 与 <code>Localization.Database</code></li><li><strong>新增</strong> 领域模型 <code>Domain</code>：实体协议接口、值对象、领域事件缓冲与规约</li><li><strong>新增</strong> 持久化：仓储、查询、工作单元与 Transaction 阶段、批量方法、雪花标识生成器；<code>Persistence.InMemory</code>、<code>Persistence.EntityFrameworkCore</code>、<code>Persistence.SqlSugar</code>（多库、分表、差异日志）与 <code>Persistence.Generators</code></li><li><strong>新增</strong> SqlSugar 读写分离：只读工作单元读从库，其余读写走主库；从库权重归一化与周期探测，不可读的自动摘除、全部不可读时读回到主库，健康项 <code>persistence.sqlsugar.replicas</code>（见<a href="./guide/persistence#读写分离">持久化</a>）</li><li><strong>新增</strong> 缓存：字节存储、类型化缓存、分布式锁、Idempotency 阶段、<code>IDistributedCache</code> 适配、键管理；<code>Caching.InMemory</code>、<code>Caching.Redis</code>、<code>Caching.Hybrid</code>、<code>Caching.Remote</code>（Experimental）</li><li><strong>新增</strong> 多租户：租户解析与 Tenant 阶段、租户分片与管道外的 <code>TenantShardScope</code>；<code>MultiTenancy.InMemory</code>、<code>MultiTenancy.Database</code></li><li><strong>新增</strong> 安全：认证处理器与 Authenticate 阶段、权限与策略、RBAC 授予、权限收窄过滤器、授予来源、条件引擎、IP 归属地；<code>Security.InMemory</code>、<code>Security.Database</code>、<code>Security.Jwt</code>、<code>Security.OpenIdConnect</code>、<code>Security.Ip2Region</code></li><li><strong>新增</strong> 消息：CloudEvents 信封、发布与订阅（竞争消费与每个实例都收到的广播订阅）、经管道的派发、重试与死信、事务性发件箱、领域事件到消息的登记；<code>Messaging.InMemory</code>、<code>Messaging.RabbitMQ</code>、<code>Messaging.Kafka</code>（流与按时刻重放）</li><li><strong>新增</strong> 对象存储：批量写入与删除、按前缀列举、范围读取、分片上传、预签名、命名存储实例；<code>ObjectStorage.FileSystem</code>、<code>ObjectStorage.S3</code></li><li><strong>新增</strong> 调度：作业与触发器、间隔 / cron / 一次 / 手动计划、日历、misfire、集群分发与失联恢复、领导选举、重试与执行时限；<code>Scheduling.InMemory</code>、<code>Scheduling.Database</code>、<code>Scheduling.Kubernetes</code></li><li><strong>新增</strong> 远程配置与密钥：<code>Configuration.Abstractions</code> 的配置源（轮询重载、失败保留最后一份）与 <code>Configuration.Nacos</code></li><li><strong>新增</strong> 审计：Observe 阶段审计中间件与查询契约；<code>Auditing.InMemory</code>、<code>Auditing.Database</code></li><li><strong>新增</strong> 可观测性：<code>Observability.OpenTelemetry</code> 导出追踪、指标与日志，<code>Observability.Host</code> 读取进程与主机运行信息</li><li><strong>新增</strong> 工作流：JSON 定义模型、定义目录、引擎、内置活动、用户任务、补偿与事件；<code>Workflow.InMemory</code>、<code>Workflow.Database</code></li><li><strong>新增</strong> AI：基于 <code>Microsoft.Extensions.AI</code> 的 Provider 目录、<code>IAIChat</code>、护栏、操作桥接成模型工具、知识库流水线；<code>AI.OpenAI</code>、<code>AI.VectorData</code></li><li><strong>新增</strong> 每个领域的一致性套件 <code>&lt;领域&gt;.Conformance</code>，默认实现与 Provider 通过同一套用例</li></ul><h3 id="宿主、协议与插件" tabindex="-1">宿主、协议与插件 <a class="header-anchor" href="#宿主、协议与插件" aria-label="Permalink to “宿主、协议与插件”">​</a></h3><ul><li><strong>新增</strong> 宿主 <code>Hosting.AspNetCore</code>（请求桥接、探针、本地化的 Problem Details、绕过管道端点的 <code>XiHan</code> 认证方案）与 <code>Hosting.CommandLine</code>（<code>help</code> / <code>graph</code> / <code>pipeline</code> / <code>operations</code> / <code>invoke</code>，按错误 KIND 的退出码）</li><li><strong>新增</strong> 协议适配器 <code>Protocols.Http</code>（路由推导、OpenAPI 3.1 与权限扩展）、<code>Protocols.Grpc</code>（由 Schema 推出 protobuf、<code>/operations.proto</code>）、<code>Protocols.Mcp</code>（Streamable HTTP 与 stdio）、<code>Protocols.CloudEvents</code>（入站 <code>/events</code> 与出站 Webhook）</li><li><strong>新增</strong> 插件协议 <code>xihan.plugin.v1</code> 与三种宿主：<code>Plugins.InProcess</code>、<code>Plugins.OutOfProcess</code>、<code>Plugins.Wasm</code>（Experimental），黑盒套件 <code>Plugins.Conformance</code></li><li><strong>新增</strong> 组合包 <code>Profiles.Minimal</code>、<code>Profiles.Standard</code>、<code>Profiles.Full</code></li><li><strong>新增</strong> 命令行工具 <code>xihan</code>：<code>pack</code> 从 <code>xihan.app.json</code> 生成 Dockerfile、Kustomize、Compose 与 Aspire 产物，<code>graph</code> / <code>pipeline</code> / <code>operations</code> / <code>invoke</code> 转发给应用</li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};